'use strict';
(function(){
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let quietState=null,quietUntil=-1;
function defer(){quietState=state;quietUntil=state.tick+2;}
const names={waiting:'En attente',running:'En cours',applied:'Réalisé',refused:'Refusé',blocked:'Non réalisé',cancelled:'Annulé'};
const symbols={waiting:'◷',running:'♫',applied:'✓',refused:'↪',blocked:'!',cancelled:'×'};
function personName(id){return state.people.find(p=>p.id===id)?.name||id;}
function responseHTML(accepted=[],refused=[]){if(!accepted.length&&!refused.length)return '';return `<div class="decision-responses"><h3>La réponse des musiciens</h3>${[...refused.map(p=>({...p,yes:false})),...accepted.map(p=>({...p,yes:true}))].map(p=>I.response(state,p)).join('')}</div>`;}
function timing(o){if(o.suspended)return 'Progression conservée · reprise prioritaire à 10 h.';return o.until>state.tick?`Encore ${Math.max(0,o.until-state.tick)*10} minutes de jeu${o.status==='waiting'?' avant que la proposition puisse être envoyée': ' avant la fin de la séance'}.`:'';}
function resumeButton(){return '<div class="outcome-actions"><button id="resumeOutcome" class="primary">Continuer la simulation →</button></div>';}
function bindResume(){ $('#resumeOutcome').onclick=()=>{dialogWasRunning=true;closeDialog();};}
function showOutcome(o){if(!o)return;if(state.music.lastSubmission?.id===o.id&&state.music.lastSubmission.duplicate&&['waiting','running'].includes(o.status)){state.music.lastSubmission=null;window.MaisonRequestFeedback?.show(o);return;}if(o.status==='waiting'){openDialog(`<section class="waiting-sheet"><span class="status-chip waiting">◷ En attente</span><h2>${o.type==='practice'?'Répétition planifiée':esc(o.title)}</h2>${o.songId&&M.song(state,o.songId)?`<strong class="song-heading">${I.songTitle(M.song(state,o.songId))}</strong>`:''}<p>${o.suspended?'Reprise à 10 h · progression conservée.':esc(o.reason)}</p><small>Démarrera automatiquement quand le groupe sera disponible.</small><div class="waiting-buttons">${!o.suspended?'<button id="cancelOutcome" class="quiet">Annuler</button>':''}${resumeButton()}</div></section>`,()=>{D.acknowledgeOrder(state,o.id);save();});bindResume();if($('#cancelOutcome'))$('#cancelOutcome').onclick=()=>{D.cancel(state,o.id);save();closeDialog(true);render();};return;}openDialog(`<span class="eyebrow">LE RÉSULTAT DE TON CHOIX · TEMPS EN PAUSE</span><div class="outcome-icon ${o.status}">${symbols[o.status]}</div><span class="status-chip ${o.status}">${names[o.status]}</span><h2>${I.songText(state,o.title)}</h2>${I.context(state,o)}<p class="outcome-reason">${I.songText(state,o.reason)}</p>${o.suspended?'<div class="outcome-next"><strong>La séance est suspendue.</strong><p>Les mêmes participants reprendront à 10 h, avant la nouvelle direction. Le temps restant est conservé, sans nouvelle invitation.</p></div>':o.status==='waiting'?`<div class="outcome-next"><strong>L’invitation n’a pas encore été envoyée.</strong><p>${esc(timing(o))} Dès que les conditions seront réunies, elle sera envoyée automatiquement, une seule fois. Les musiciens pourront alors accepter ou refuser. Le démarrage sera annoncé par un bandeau transparent. Les décisions importantes garderont leur fenêtre.</p><p>Elle reste visible dans « Tes propositions » dans « Activité de la maison ».</p></div>`:o.status==='running'?`<div class="outcome-next"><strong>La séance a réellement commencé.</strong><p>${esc(timing(o))} ${o.type==='trial'?'Une fenêtre annoncera le vote du groupe.':'La préparation progressera à la fin de la séance.'}</p></div>`:o.status==='refused'||o.status==='blocked'?'<div class="outcome-next"><strong>Aucune action n’est en attente.</strong><p>Tu peux modifier ta proposition ou la refaire plus tard. Elle ne sera pas relancée automatiquement.</p></div>':''}${responseHTML(o.accepted,o.refused)}${o.status==='waiting'&&!o.suspended?`<button class="cancel-order" id="cancelOutcome">Annuler cette proposition</button>`:''}${resumeButton()}`,()=>{D.acknowledgeOrder(state,o.id);save();});bindResume();if($('#cancelOutcome'))$('#cancelOutcome').onclick=()=>{D.cancel(state,o.id);save();render();showOutcome(o);};}
function comparison(r){const sign=n=>(n>=0?'+':'')+n;return `<table class="rework-comparison"><caption>Avant / après la seule réécriture</caption><thead><tr><th>Capacité</th><th>Avant</th><th>Après</th><th>Variation</th></tr></thead><tbody>${[['Niveau / 7','level'],['Tours','turns'],['Énergie / tour','energyPerTurn']].map(([name,key])=>`<tr><th>${name}</th><td>${r.before[key]}</td><td>${r.after[key]}</td><td class="${r.after[key]>r.before[key]?'gain':r.after[key]<r.before[key]?'loss':'neutral'}">${sign(r.after[key]-r.before[key])}</td></tr>`).join('')}</tbody></table>`;}
function showMoment(m){openDialog(`<span class="eyebrow">UN MOMENT QUI FAÇONNE LE GROUPE · SEMAINE ${day(m.tick)}</span><div class="moment-symbol">${({adoption:'♫',rejection:'↪',ready:'✦',composition:'♪',arrival:'＋',influence:'↗',duo:'♡',order:'◷'})[m.kind]||'✦'}</div><h2>${esc(m.title)}</h2>${I.context(state,m)}<p class="moment-body">${I.songText(state,m.body)}</p>${m.rework?comparison(m.rework):''}${m.votes?`<div class="vote-count"><strong>${m.votes.filter(v=>v.yes).length} / ${m.votes.length}</strong><span>avis favorables · majorité requise : ${Math.floor(m.votes.length/2)+1}</span></div><div class="votes">${m.votes.map(v=>I.response(state,v,{vote:true})).join('')}</div>`:''}<div class="moment-consequences"><strong>Ce que ça change</strong><ul>${(m.consequences||[]).map(c=>`<li>${I.songText(state,c)}</li>`).join('')}</ul></div>${responseHTML(m.accepted,m.refused)}${m.kind==='adoption'?`<div class="adoption-rewards">${state.music.pending.filter(e=>e.rewardSource==='adoption'&&e.songId===m.songId).map(e=>`<button data-adoption-reward="${e.id}">✦ Carte pour ${esc(personName(e.personId))} ↗</button>`).join('')}</div>`:''}${m.songId?'<button id="momentSong" class="quiet">Voir la chanson et sa préparation ↗</button>':''}${resumeButton()}`,()=>{D.acknowledge(state,m.id);save();renderTracker();});bindResume();document.querySelectorAll('[data-adoption-reward]').forEach(b=>b.onclick=()=>{D.acknowledge(state,m.id);save();renderTracker();window.MaisonMusicUI.showStory(b.dataset.adoptionReward);});if($('#momentSong'))$('#momentSong').onclick=()=>{D.acknowledge(state,m.id);save();renderTracker();window.MaisonMusicUI.showSong(m.songId);};}
function maybeShow(){if(quietState===state&&state.tick<quietUntil)return false;if(window.homeOpen)return false;if($('#dialog').open||globalThis.MaisonShows?.busy(state)||globalThis.MaisonWeeks?.blocked(state)||globalThis.MaisonWeeks?.isNight(state))return false;const m=state.music.moments.find(m=>!m.seen&&!D.isTransient(m));if(!m)return false;showMoment(m);save();return true;}
function showHistory(){const moments=state.music.moments.slice().reverse();openDialog(`<span class="eyebrow">LA MÉMOIRE DU COLLECTIF</span><h2>Les moments du groupe.</h2><p>Les décisions importantes restent ici, même après avoir fermé leur fenêtre.</p><div class="moment-history">${moments.length?moments.map(m=>`<button class="history-row" data-moment="${m.id}"><span>S${day(m.tick)} · ${clock(m.tick)}</span><strong>${esc(m.title)}</strong><small>${I.songText(state,m.body)}</small>${!m.seen?'<b>Nouveau</b>':''}</button>`).join(''):'<p>Les premières décisions importantes apparaîtront ici.</p>'}</div>`);document.querySelectorAll('[data-moment]').forEach(b=>b.onclick=()=>showMoment(state.music.moments.find(m=>m.id===b.dataset.moment)));}
function renderTracker(){const active=D.ordered(state).filter(o=>!D.isDone(o)),recent=state.music.orders.filter(D.isDone).slice(0,2),rows=[...active,...recent],el=$('#decisionTracker');el.hidden=!rows.length;const unseen=state.music.moments.filter(m=>!m.seen).length;$('#groupMoments').textContent='✦ Moments'+(unseen?' · '+unseen:'');if(!rows.length)return;el.innerHTML=`<div class="tracker-heading"><div><span class="eyebrow">TES PROPOSITIONS</span><strong>${active.length?active.length+' en attente ou en cours':'Les derniers résultats'}</strong></div><span class="tiny">Les refus ne sont jamais relancés automatiquement.</span></div><div class="order-list"><div class="page-items">${(window.MaisonPages?.slice('orders',rows,3)||rows).map(o=>{const gate=o.status==='waiting'?D.preflight(state,o):null;return `<div class="order-row"><span class="status-chip ${o.status}">${symbols[o.status]} ${names[o.status]}</span><div><strong>${I.songText(state,o.title)}</strong><p>${esc(gate?.reason||o.reason)}</p>${o.until>state.tick?'<small>'+esc(timing(o))+'</small>':''}</div><button class="quiet" data-order="${o.id}">Détails ↗</button>${o.status==='waiting'&&!o.suspended?`<button class="quiet" data-cancel-order="${o.id}" aria-label="Annuler ${I.songText(state,o.title)}">Annuler</button>`:''}</div>`;}).join('')}</div>${window.MaisonPages?.nav('orders')||''}</div>`;window.MaisonPages?.bind(el,renderTracker);el.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>showOutcome(state.music.orders.find(o=>o.id===b.dataset.order)));el.querySelectorAll('[data-cancel-order]').forEach(b=>b.onclick=()=>{D.cancel(state,b.dataset.cancelOrder);save();renderTracker();});}
function renderFeedback(){window.MaisonHouseFlowUI?.render();renderTracker();maybeShow();}
$('#groupMoments').onclick=showHistory;window.MaisonDecisionsUI={render:renderFeedback,showOutcome,maybeShow,defer};renderFeedback();
})();
